def heuristic(row, col, goal_row, goal_col, grid, size):
    """Return admissible heuristic estimate. Must never overestimate true distance.
    Args: row,col = current position; goal_row,goal_col = target; grid = 2D list (1=obstacle); size = grid dimension
    Returns: float, admissible h-value"""
    return abs(row - goal_row) + abs(col - goal_col)
